CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', sex text NOT NULL DEFAULT 'male' CHECK (sex IN ('male','female')), age integer NOT NULL DEFAULT 47 CHECK(age BETWEEN 18 AND 100), height numeric NOT NULL DEFAULT 177 CHECK(height BETWEEN 100 AND 230), weight numeric NOT NULL DEFAULT 69 CHECK(weight BETWEEN 30 AND 300), target_weight numeric NOT NULL DEFAULT 75 CHECK(target_weight BETWEEN 30 AND 300), activity numeric NOT NULL DEFAULT 1.55 CHECK(activity BETWEEN 1.2 AND 1.9), training_days integer NOT NULL DEFAULT 4 CHECK(training_days BETWEEN 0 AND 7), shifts boolean NOT NULL DEFAULT false, onboarded boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id=(select auth.uid())) WITH CHECK(id=(select auth.uid()));
CREATE FUNCTION public.create_massafit_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END; $$;
CREATE TRIGGER massafit_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_massafit_profile();
CREATE TABLE public.goals (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, surplus integer NOT NULL DEFAULT 350 CHECK(surplus BETWEEN 250 AND 500), calories integer NOT NULL CHECK(calories BETWEEN 1000 AND 7000), protein numeric NOT NULL CHECK(protein BETWEEN 30 AND 600), fat numeric NOT NULL CHECK(fat BETWEEN 20 AND 300), carbs numeric NOT NULL CHECK(carbs BETWEEN 0 AND 1200), water integer NOT NULL DEFAULT 3000 CHECK(water BETWEEN 500 AND 8000));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.goals TO authenticated; GRANT ALL ON public.goals TO service_role;
ALTER TABLE public.goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_goals ON public.goals FOR ALL TO authenticated USING (user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE TABLE public.food_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, calories numeric NOT NULL, protein numeric NOT NULL, fat numeric NOT NULL, carbs numeric NOT NULL, portion_label text NOT NULL, portion_grams numeric NOT NULL CHECK(portion_grams>0));
GRANT SELECT ON public.food_items TO authenticated; GRANT ALL ON public.food_items TO service_role;
ALTER TABLE public.food_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.food_items FOR SELECT TO authenticated USING(true);
