CREATE TABLE public.meal_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, food_id uuid REFERENCES public.food_items(id), name text NOT NULL, meal text NOT NULL, grams numeric NOT NULL CHECK(grams>0 AND grams<=3000), calories numeric NOT NULL, protein numeric NOT NULL, fat numeric NOT NULL, carbs numeric NOT NULL, day date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.meal_logs TO authenticated; GRANT ALL ON public.meal_logs TO service_role;
ALTER TABLE public.meal_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_meals ON public.meal_logs FOR ALL TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE INDEX meals_user_day ON public.meal_logs(user_id,day);
CREATE TABLE public.water_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, amount integer NOT NULL CHECK(amount BETWEEN 50 AND 3000), day date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.water_logs TO authenticated; GRANT ALL ON public.water_logs TO service_role;
ALTER TABLE public.water_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_water ON public.water_logs FOR ALL TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE INDEX water_user_day ON public.water_logs(user_id,day);
CREATE TABLE public.weight_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, weight numeric NOT NULL CHECK(weight BETWEEN 30 AND 300), day date NOT NULL DEFAULT CURRENT_DATE, UNIQUE(user_id,day));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.weight_logs TO authenticated; GRANT ALL ON public.weight_logs TO service_role;
ALTER TABLE public.weight_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_weight ON public.weight_logs FOR ALL TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE TABLE public.supplement_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Creatina', dose numeric NOT NULL DEFAULT 5 CHECK(dose BETWEEN 3 AND 5), day date NOT NULL DEFAULT CURRENT_DATE, UNIQUE(user_id,name,day));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.supplement_logs TO authenticated; GRANT ALL ON public.supplement_logs TO service_role;
ALTER TABLE public.supplement_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_supplements ON public.supplement_logs FOR ALL TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE TABLE public.food_favorites (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, food_id uuid NOT NULL REFERENCES public.food_items(id) ON DELETE CASCADE, PRIMARY KEY(user_id,food_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.food_favorites TO authenticated; GRANT ALL ON public.food_favorites TO service_role;
ALTER TABLE public.food_favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_favorites ON public.food_favorites FOR ALL TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));